Das Grundproblem: Die Preise stecken in der Logik. Wenn man die Tarife als Daten beschreibt, bleibt die Logik ein paar Zeilen lang und ein neues Land ist eine neue Zeile in einer Tabelle.

```python
from bisect import bisect_left
from dataclasses import dataclass
from decimal import Decimal


class VersandNichtMoeglich(ValueError):
    """Land wird nicht beliefert oder Paket ist zu schwer."""


@dataclass(frozen=True)
class Tarif:
    gewichtsgrenzen: tuple[Decimal, ...]   # Obergrenze je Stufe in kg, aufsteigend
    preise: tuple[Decimal, ...]            # Preis je Stufe
    express_zuschlag: Decimal
    pauschale: Decimal = Decimal("0.00")   # z. B. Zollabwicklung

    def __post_init__(self) -> None:
        if len(self.gewichtsgrenzen) != len(self.preise):
            raise ValueError("gewichtsgrenzen und preise müssen gleich lang sein")
        if list(self.gewichtsgrenzen) != sorted(self.gewichtsgrenzen):
            raise ValueError("gewichtsgrenzen müssen aufsteigend sortiert sein")

    def preis(self, gewicht: Decimal, express: bool = False) -> Decimal:
        if gewicht <= 0:
            raise ValueError(f"Gewicht muss positiv sein, nicht {gewicht}")
        stufe = bisect_left(self.gewichtsgrenzen, gewicht)
        if stufe == len(self.gewichtsgrenzen):
            raise VersandNichtMoeglich(
                f"{gewicht} kg überschreitet das Maximum von {self.gewichtsgrenzen[-1]} kg"
            )
        preis = self.preise[stufe] + self.pauschale
        if express:
            preis += self.express_zuschlag
        return preis


def _d(*werte: str) -> tuple[Decimal, ...]:
    return tuple(Decimal(w) for w in werte)


STANDARD_GRENZEN = _d("2", "5", "10", "31.5")
EU_PREISE = _d("11.99", "15.99", "21.99", "32.99")

TARIFE: dict[str, Tarif] = {
    "inland": Tarif(STANDARD_GRENZEN, _d("4.99", "6.99", "9.49", "16.49"), Decimal("8")),
    "at": Tarif(STANDARD_GRENZEN, _d("9.99", "12.99", "17.99", "26.99"), Decimal("15")),
    "eu1": Tarif(STANDARD_GRENZEN, EU_PREISE, Decimal("15")),
    "ch": Tarif(STANDARD_GRENZEN, EU_PREISE, Decimal("20"), pauschale=Decimal("6.50")),
}

LAND_ZU_TARIF: dict[str, str] = {
    "DE": "inland",
    "AT": "at",
    **dict.fromkeys(["FR", "NL", "BE", "LU", "IT", "ES"], "eu1"),
    "CH": "ch",
}


def versandkosten(land: str, gewicht: Decimal | float | str, express: bool = False) -> Decimal:
    try:
        tarif = TARIFE[LAND_ZU_TARIF[land.upper()]]
    except KeyError:
        raise VersandNichtMoeglich(f"Kein Versand nach {land!r}") from None
    return tarif.preis(Decimal(str(gewicht)), express)
```

Was sich geändert hat:

| Vorher | Nachher |
|---|---|
| Preise als `float`, am Ende `round()` | `Decimal`, keine Rundungsfehler bei Geldbeträgen |
| `if gewicht <= …`-Kaskade pro Land | `bisect_left` sucht die erste Grenze ≥ Gewicht |
| `None` bei unbekanntem Land / zu schwer | eigene Exception mit Begründung |
| Express-Zuschlag per `if land == "DE"` | Teil des Tarifs |

Polen und Tschechien sind dann nur noch ein neuer Eintrag in `TARIFE` und zwei Zeilen in `LAND_ZU_TARIF`. Wenn die Preise irgendwann aus einer Datei oder dem Admin-Bereich kommen sollen, baust du die `Tarif`-Objekte einfach aus JSON statt im Code.

**Achtung, eine Verhaltensänderung:** Die alte Funktion gab `None` zurück, die neue wirft `VersandNichtMoeglich`. Such alle Aufrufer (`grep -rn "versandkosten(" .`) und fang die Exception dort ab, wo bisher auf `None` geprüft wurde.

Damit du sicher bist, dass für die bestehenden Länder dasselbe rauskommt, lass einmal einen Vergleich gegen die alte Version laufen (alte Funktion vorher in `alte_versandkosten` umbenennen):

```python
from itertools import product

for land, g, ex in product(["DE", "AT", "FR", "ES", "XX"], [0.5, 2, 2.01, 9.99, 31.5, 40], [False, True]):
    alt = alte_versandkosten(land, g, ex)
    try:
        neu = versandkosten(land, g, ex)
    except VersandNichtMoeglich:
        neu = None
    assert (alt is None and neu is None) or Decimal(str(alt)) == neu, (land, g, ex, alt, neu)
print("identisch")
```

