```python
import re
from datetime import date

MONATE = {
    "januar": 1, "jan": 1, "februar": 2, "feb": 2, "märz": 3, "maerz": 3, "mär": 3, "mrz": 3,
    "april": 4, "apr": 4, "mai": 5, "juni": 6, "jun": 6, "juli": 7, "jul": 7,
    "august": 8, "aug": 8, "september": 9, "sep": 9, "sept": 9, "oktober": 10, "okt": 10,
    "november": 11, "nov": 11, "dezember": 12, "dez": 12,
}

_NUMERISCH = re.compile(r"^(\d{1,2})\.\s*(\d{1,2})\.\s*(\d{2}|\d{4})$")
_TEXT = re.compile(r"^(\d{1,2})\.?\s+([a-zäöü]+)\.?\s+(\d{4})$", re.IGNORECASE)
_ISO = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")


def parse_datum(text: str, *, pivot: int = 70) -> date:
    s = text.strip()
    if m := _ISO.match(s):
        j, mo, t = map(int, m.groups())
        return date(j, mo, t)
    if m := _NUMERISCH.match(s):
        t, mo, j = m.groups()
        jahr = int(j)
        if len(j) == 2:
            jahr += 1900 if jahr >= pivot else 2000
        return date(jahr, int(mo), int(t))
    if m := _TEXT.match(s):
        t, name, j = m.groups()
        try:
            mo = MONATE[name.lower()]
        except KeyError:
            raise ValueError(f"Unbekannter Monat: {name!r}") from None
        return date(int(j), mo, int(t))
    raise ValueError(f"Kein gültiges Datum: {text!r}")
```

Ich würde das so lösen: Text mit `pypdf` aus den ersten zwei Seiten ziehen, Nummer und Datum über eine Liste von Regex-Mustern suchen und den Lieferanten über eine kleine Zuordnungstabelle erkennen (Firmenname oder USt-IdNr. im Text → Kurzname). Standardmäßig zeigt das Skript nur an, mit `--ausfuehren` benennt es wirklich um und schreibt ein Protokoll, mit dem du alles rückgängig machen kannst.

```bash
pip install pypdf
```

```python
#!/usr/bin/env python3
"""Benennt PDF-Rechnungen nach Datum, Rechnungsnummer und Lieferant um."""
import argparse
import csv
import re
from datetime import date
from pathlib import Path

from pypdf import PdfReader
from pypdf.errors import PyPdfError

# Suchbegriff im PDF-Text -> Kurzname im Dateinamen. Die USt-IdNr. ist am eindeutigsten.
LIEFERANTEN = {
    "Schäfer Bürobedarf": "Schaefer",
    "DE123456789": "Mueller-IT",
    "Stadtwerke Musterstadt": "Stadtwerke",
    "Elektro Kowalski": "Kowalski",
}

NUMMER_MUSTER = [
    # Rechnungsnummer, Rechnungs-Nr., Rechnung Nr., Rechnungsnr
    re.compile(r"Rechnungs?[-\s]?(?:nummer|nr\.?)\s*:?\s*([A-Z0-9][A-Z0-9/\-]*\d)", re.IGNORECASE),
    re.compile(r"Beleg[-\s]?(?:nummer|nr\.?)\s*:?\s*([A-Z0-9][A-Z0-9/\-]*\d)", re.IGNORECASE),
]

MONATE = {
    "januar": 1, "februar": 2, "märz": 3, "april": 4, "mai": 5, "juni": 6,
    "juli": 7, "august": 8, "september": 9, "oktober": 10, "november": 11, "dezember": 12,
}

# Reihenfolge = Priorität. \bDatum, damit "Lieferdatum" nicht als Rechnungsdatum zählt.
DATUM_LABELS = ["Rechnungsdatum", "Belegdatum", r"\bDatum"]


def lies_text(pdf: Path, seiten: int = 2) -> str:
    reader = PdfReader(pdf)
    if reader.is_encrypted:
        reader.decrypt("")  # viele "geschützte" Rechnungen haben nur ein leeres Passwort
    return "\n".join(seite.extract_text() or "" for seite in reader.pages[:seiten])


def finde_nummer(text: str) -> str | None:
    for muster in NUMMER_MUSTER:
        if m := muster.search(text):
            return m.group(1)
    return None


def finde_datum(text: str) -> date | None:
    for label in DATUM_LABELS:
        vorspann = label + r"\s*:?\s*"
        if m := re.search(vorspann + r"(\d{1,2})\.(\d{1,2})\.(\d{4})", text, re.IGNORECASE):
            tag, monat, jahr = map(int, m.groups())
        elif m := re.search(vorspann + r"(\d{1,2})\.\s*([^\W\d_]+)\s+(\d{4})", text, re.IGNORECASE):
            monat = MONATE.get(m.group(2).lower())
            if monat is None:
                continue
            tag, jahr = int(m.group(1)), int(m.group(3))
        else:
            continue
        try:
            return date(jahr, monat, tag)
        except ValueError:
            continue  # z. B. 31.02. -> nächstes Label probieren
    return None


def finde_lieferant(text: str) -> str:
    for suchbegriff, kurzname in LIEFERANTEN.items():
        if suchbegriff.lower() in text.lower():
            return kurzname
    return "Unbekannt"


def neuer_name(text: str) -> str | None:
    nummer, datum = finde_nummer(text), finde_datum(text)
    if not (nummer and datum):
        return None
    nummer = re.sub(r'[\\/:*?"<>|\s]+', "-", nummer)  # "2024/123" -> "2024-123"
    return f"{datum:%Y-%m-%d}_{nummer}_{finde_lieferant(text)}.pdf"


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("ordner", type=Path)
    ap.add_argument("--ausfuehren", action="store_true", help="wirklich umbenennen (sonst nur anzeigen)")
    args = ap.parse_args()

    geplant: list[tuple[Path, Path]] = []
    vergeben: set[Path] = set()
    nicht_erkannt: list[str] = []

    for pdf in sorted(args.ordner.glob("*.pdf")):
        try:
            text = lies_text(pdf)
        except (PyPdfError, OSError) as e:
            print(f"FEHLER    {pdf.name}: {e}")
            nicht_erkannt.append(pdf.name)
            continue

        name = neuer_name(text)
        if name is None:
            nicht_erkannt.append(pdf.name)
            continue

        ziel, n = pdf.with_name(name), 2
        while ziel in vergeben or (ziel.exists() and ziel != pdf):
            ziel = pdf.with_name(f"{Path(name).stem}_{n}.pdf")
            n += 1
        if ziel == pdf:
            continue  # heißt schon richtig, z. B. beim zweiten Durchlauf
        vergeben.add(ziel)
        geplant.append((pdf, ziel))
        print(f"{pdf.name:40} -> {ziel.name}")

    if args.ausfuehren and geplant:
        with (args.ordner / "umbenennung.csv").open("a", encoding="utf-8", newline="") as f:
            protokoll = csv.writer(f, delimiter=";")
            for alt, neu in geplant:
                alt.rename(neu)
                protokoll.writerow([alt.name, neu.name])

    print(f"\n{len(geplant)} Dateien {'umbenannt' if args.ausfuehren else 'würden umbenannt'}, "
          f"{len(nicht_erkannt)} nicht erkannt")
    for name in nicht_erkannt:
        print(f"  ? {name}")


if __name__ == "__main__":
    main()
```

So gehst du am besten vor:

1. `python rechnungen_umbenennen.py C:\Pfad\zu\Rechnungen` laufen lassen und die Liste anschauen.
2. Für die Dateien unter "nicht erkannt" den Text anschauen, damit du siehst, wie der Lieferant das schreibt:
   ```bash
   python -c "from pypdf import PdfReader; print(PdfReader('scan_0042.pdf').pages[0].extract_text())"
   ```
   Dann ein Muster in `NUMMER_MUSTER` oder einen Eintrag in `LIEFERANTEN` ergänzen.
3. Wenn die Vorschau passt: dasselbe mit `--ausfuehren`.

Ein paar Details:

- Die Nummer muss mit einer Ziffer enden. So landet bei "Rechnungsnummer: RE-2024-0815 vom 15.03." nicht das "vom" im Namen.
- Zwei Rechnungen mit gleichem Namen bekommen `_2`, `_3` usw. Ein zweiter Lauf über schon umbenannte Dateien ändert nichts.
- `umbenennung.csv` enthält alt;neu. Zum Rückgängigmachen reicht eine Schleife, die die Spalten vertauscht.
- Liefert `extract_text()` bei einzelnen Dateien nur Leerstring, sind das doch Scans. Die kannst du mit `ocrmypdf` vorher durch eine Texterkennung schicken.

