# rollladen/wetter.py
import requests

BASIS_URL = "https://api.open-meteo.com/v1/forecast"


class WetterFehler(Exception):
    pass


def aktuelles_wetter(lat: float, lon: float, session: requests.Session | None = None) -> dict:
    s = session or requests.Session()
    try:
        r = s.get(BASIS_URL, params={
            "latitude": lat,
            "longitude": lon,
            "current": "temperature_2m,wind_speed_10m,precipitation",
            "timezone": "Europe/Berlin",
        }, timeout=10)
        r.raise_for_status()
    except requests.RequestException as e:
        raise WetterFehler(f"Wetterdienst nicht erreichbar: {e}") from e
    daten = r.json()["current"]
    return {
        "temperatur": daten["temperature_2m"],
        "wind_kmh": daten["wind_speed_10m"],
        "regen_mm": daten["precipitation"],
        "frost": daten["temperature_2m"] <= 0,
    }


def soll_rolllaeden_schliessen(wetter: dict) -> bool:
    return wetter["wind_kmh"] >= 50 or wetter["frost"]
```

