```python
# aufraeumen.py
import shutil
from pathlib import Path

KATEGORIEN = {
    "Bilder": {".jpg", ".jpeg", ".png", ".gif", ".heic"},
    "Dokumente": {".pdf", ".docx", ".xlsx", ".odt", ".txt"},
    "Archive": {".zip", ".rar", ".7z", ".tar", ".gz"},
    "Installer": {".exe", ".msi", ".dmg", ".deb"},
}


def kategorie_fuer(datei: Path) -> str:
    endung = datei.suffix.lower()
    for name, endungen in KATEGORIEN.items():
        if endung in endungen:
            return name
    return "Sonstiges"


def zielpfad(ordner: Path, datei: Path) -> Path:
    ziel = ordner / kategorie_fuer(datei) / datei.name
    n = 1
    while ziel.exists():
        ziel = ziel.with_name(f"{datei.stem} ({n}){datei.suffix}")
        n += 1
    return ziel


def aufraeumen(ordner: Path, trocken: bool = False) -> list[tuple[Path, Path]]:
    verschoben = []
    for datei in sorted(ordner.iterdir()):
        if not datei.is_file() or datei.name.startswith("."):
            continue
        ziel = zielpfad(ordner, datei)
        if not trocken:
            ziel.parent.mkdir(exist_ok=True)
            shutil.move(datei, ziel)
        verschoben.append((datei, ziel))
    return verschoben
